return ['domain'=>'blockstudio','plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'mr','project-id-version'=>'Blockstudio','po-revision-date'=>'2026-10-23 15:34+0000','messages'=>['Blockstudio'=>'Blockstudio','The "%1$s" attribute on a %2$s block tag is dropped because the block declares no field with that id. Declare the field, or write it as a data-, aria- or html- attribute to put it on the root element.'=>'%2$s ब्लॉक टॅगवरील "%1$s" हा गुणधर्म वगळला आहे, कारण ब्लॉकमध्ये त्या ID चे कोणतेही फील्ड घोषित केलेले नाही. फील्ड घोषित करा किंवा तो मूळ घटकावर ठेवण्यासाठी data-, aria- किंवा html- गुणधर्म म्हणून लिहा.','This storage key is not declared by the block or its extensions.'=>'ही स्टोरेज की ब्लॉक किंवा त्याच्या विस्तारांमध्ये घोषित केलेली नाही.','This top-level key is not an attribute of the block, so it is ignored.'=>'ही शीर्ष-स्तरीय की ब्लॉकचा गुणधर्म नाही, त्यामुळे ती दुर्लक्षित केली जाते.','This key is only read inside the blockstudio object, which is missing.'=>'ही की फक्त blockstudio ऑब्जेक्टमध्ये वाचली जाते; तो ऑब्जेक्ट उपलब्ध नाही.','This value is not among the field options.'=>'हे मूल्य फील्डच्या पर्यायांमध्ये नाही.','This value has an unsupported shape for the field.'=>'या फील्डसाठी या मूल्याचा आकार समर्थित नाही.','This repeater has fewer rows than its minimum.'=>'या रिपीटरमध्ये किमान मर्यादेपेक्षा कमी पंक्ती आहेत.','This repeater has more rows than its maximum.'=>'या रिपीटरमध्ये कमाल मर्यादेपेक्षा जास्त पंक्ती आहेत.','This storage key has conflicting field definitions.'=>'या स्टोरेज कीसाठी फील्डच्या व्याख्या परस्परविरोधी आहेत.','The nested field value overrides this top-level value.'=>'नेस्टेड फील्डचे मूल्य हे वरच्या स्तरावरील मूल्याला अधिलिखित करते.','Extension bindings read this value only from blockstudio.attributes.'=>'विस्तार बाइंडिंग हे मूल्य फक्त blockstudio.attributes मधून वाचतात.','Blockstudio field values must be stored in an object.'=>'Blockstudio फील्डची मूल्ये ऑब्जेक्टमध्ये साठवली पाहिजेत.','Blockstudio is preparing its block cache. Pl